#include "../SDK/ChangedBlocks.h"
#include <iostream>
int wmain(int argc,wchar_t** argv){try{
 if(argc==2&&!wcscmp(argv[1],L"--preview")){std::cout<<"Changed Block Tracking SDK | OFFLINE PREVIEW\nObserve conservative changed ranges on an explicitly selected scratch disk. No driver or disk is opened.\n";return 0;}
 if(argc==2&&!wcscmp(argv[1],L"--disks")){for(const auto& d:ChangedBlocks::Disks())std::cout<<"Disk "<<d.number<<" | "<<ChangedBlocks::Utf8(d.name)<<" | "<<ChangedBlocks::Utf8(d.reason)<<"\n";return 0;}
 ChangedBlocks::Tracker tracker;auto devices=tracker.Devices();if(argc==2&&!wcscmp(argv[1],L"--devices")){for(const auto& d:devices)std::wcout<<d.id<<L" | "<<reinterpret_cast<const wchar_t*>(d.pdo_name)<<L"\n";return 0;}
 if(argc!=3||wcscmp(argv[1],L"--track")){std::cout<<"ChangedBlocksCLI.exe --disks | --devices | --track ID\nOnly the explicitly attached 64 MiB Titan Storage Fault Lab scratch disk is accepted. Establish the baseline externally first.\n";return 2;}
 const std::wstring input=argv[2];if(input.empty()||input.find_first_not_of(L"0123456789")!=input.npos)return 2;tracker.Start(std::stoull(input),64ull*1024*1024);std::cout<<"Tracking. Commands: checkpoint, acknowledge, activate, stop. No disk reads/writes are generated by this viewer.\n";uint64_t generation=0;
 for(std::string command;std::getline(std::cin,command);){if(command=="stop")break;if(command=="activate"){std::string key;std::cout<<"Product key (not saved): ";std::getline(std::cin,key);auto error=tracker.Verification(key);SecureZeroMemory(key.data(),key.size());std::cout<<(error.empty()?"Full access activated for this Windows boot.":error)<<"\n";}else if(command=="acknowledge"){tracker.Acknowledge(generation);std::cout<<"Exact checkpoint acknowledged. Tracking continues in the next interval.\n";}else{auto map=tracker.Checkpoint();generation=map.state.generation;std::cout<<map.state.changed_blocks<<" changed blocks; generation "<<generation<<".\n";map.ForEachRange([](const auto& range){std::cout<<"offset="<<range.offset<<" length="<<range.length<<"\n";return true;});}}
 tracker.Stop();return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<"\n";return 1;}}
